// Pre-rendered 2-bit anti-aliased bitmap fonts (generated by tools/fontgen.py into src/app/gen/fonts*.cpp).
#pragma once
#include <cstdint>

namespace x4 {

enum class FontWeight : uint8_t { Regular, Bold, Mono, Semi };   // Semi = 600 (Sleek labels and units)

// Typeface families. Classic = Atkinson Hyperlegible (+ IBM Plex Mono). The others are the Sleek display style's faces
// (docs/DISPLAY_STYLES_PLAN.md): ArchivoCond is Archivo at 75 % width (Archivo's display face).
enum class Face : uint8_t { Classic, ArchivoCond, Archivo, Bricolage, Fraunces, Geist, Count };

struct Glyph {
  uint16_t cp;
  uint8_t w, h;
  int8_t xoff, yoff;  // yoff = top of bitmap relative to baseline (negative = above)
  uint8_t adv;
  uint32_t off;       // offset into the font's 2 bpp blob
};

struct FontData {
  Face face;
  FontWeight weight;
  uint8_t size, ascent, descent, digitAdv;   // digitAdv: widest digit (tabular figures); 0 = face has none
  uint16_t count;
  const Glyph* glyphs;   // sorted by cp
  const uint8_t* bits;
};

struct FontTable { const FontData* fonts; const int* count; };
extern const FontData kFonts[];        // Classic (gen/fonts.cpp)
extern const int kFontCount;
extern const FontTable kFontTables[];  // every generated table (gen/fonts_index.cpp)
extern const int kFontTableCount;

// Closest available font of a face (same weight preferred; ties → the smaller size). A face without any font falls
// back to Classic. findFontExact() returns nullptr unless exactly (face, weight, size) exists.
const FontData* findFont(Face face, FontWeight w, int size);
const FontData* findFontExact(Face face, FontWeight w, int size);
const Glyph* findGlyph(const FontData* f, uint32_t cp);

}  // namespace x4
